{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Relation classes for an auto-wrong line, in the brief's first-match-wins order.</summary>
public static class Relation
{
	/// <summary>Expected (key) label is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Raw line carries a can/jar unit; the key row is Canned and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>The key head phrase has two or more words and the parsed name equals only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Head terms agree after singularising and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Head terms and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Head terms agree and nothing above holds.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Nothing above holds, or a relation check needed a trace field the line lacks.</summary>
	public const string Other = "other";
}

/// <summary>Decision sites for an auto-wrong line.</summary>
public static class Site
{
	/// <summary>Path ranker and the line reused an existing row.</summary>
	public const string Reuse = "reuse";

	/// <summary>Path override.</summary>
	public const string Override = "override";

	/// <summary>Path curated.</summary>
	public const string Curated = "curated";

	/// <summary>Path ranker, not reused.</summary>
	public const string Ranker = "ranker";
}

/// <summary>
/// Classifies one auto-wrong trace line (accepted row vs key row) using the production helpers —
/// <see cref="FdcNormalizer.NormalizeToTokens(string)"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>
/// and <see cref="IngredientLineResolver.SingularizeToken"/> — never a copy of their logic (D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state/modifier probe; the runner is single-threaded.
	private readonly List<string> _singleToken = [];

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Creates a classifier over the production normalizer and the exact-overrides key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. <see cref="ClassificationResult.Site"/> is empty when the atom
	/// path is unknown; the runner refuses to emit a census that contains such a line.
	/// </summary>
	/// <param name="line">The trace line (auto == true, correct == false).</param>
	/// <returns>The classification with relation, site, tiers, state masks and the audit columns.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
		var keyDesc = FirstOrEmpty(line.ExpectedDescriptions);
		var acceptedDesc = FirstOrEmpty(line.ActualDescriptions);
		var keyTier = FirstOrEmpty(line.ExpectedDataTypes);
		var acceptedTier = FirstOrEmpty(line.ActualDataTypes);
		var parsedName = atom?.ParsedName ?? string.Empty;

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			ParsedName = parsedName,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			RawText = line.RawText,
		};

		if (atom is null || !IsKnownPath(atom.Path))
		{
			return result;
		}

		result.Site = SiteOf(atom);
		if (result.Site == Site.Override)
		{
			result.OverrideKey = _overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no";
		}

		result.Relation = ClassifyRelation(line, parsedName, result);
		return result;
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to (not including) the first
	/// token production state/modifier vocabulary marks as non-head — <see cref="FdcLexicon.ModifierWords"/>
	/// or a non-<see cref="FoodState.None"/> answer from <see cref="FdcMatcher.ExtractCandidateState"/> /
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>. "Bread, crumbs, dry, grated, plain" gives
	/// <c>[bread, crumbs]</c>; "Tomatoes, crushed, canned" gives <c>[tomato]</c>.
	/// </summary>
	/// <param name="tokens">Normalized key-description tokens.</param>
	/// <returns>The head-phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The key head phrase for a key description string.</summary>
	/// <param name="description">The key row description.</param>
	/// <returns>The head-phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhraseOf(string description) => KeyHeadPhrase(_normalizer.NormalizeToTokens(description));

	/// <summary>Normalized, singularised tokens of a free-text name (production normalizer + resolver singulariser).</summary>
	/// <param name="text">The name text.</param>
	/// <returns>The tokens.</returns>
	public IReadOnlyList<string> SingularPhrase(string text) => _normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	/// <summary>
	/// The state mask production matching uses for a token list:
	/// <see cref="FdcMatcher.ExtractCandidateState"/> ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// (the matcher feeds both into <c>StateAgrees</c>).
	/// </summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Folds a raw line text for the <c>exact-overrides.json</c> key lookup — the same folding
	/// <c>FdcMatcher</c> applies before its raw-key override probe (lower-cased, trimmed, content from
	/// the first <c>(</c> dropped).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var paren = rawText.IndexOf('(', StringComparison.Ordinal);
		var text = paren >= 0 ? rawText[..paren] : rawText;
#pragma warning disable CA1308 // Reason: parity with FdcMatcher's nameClean override-lookup folding.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	private string ClassifyRelation(TraceLine line, string parsedName, ClassificationResult result)
	{
		var keyDesc = FirstOrEmpty(line.ExpectedDescriptions);
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return Relation.NoLabel;
		}

		var acceptedDesc = FirstOrEmpty(line.ActualDescriptions);
		var keyTier = FirstOrEmpty(line.ExpectedDataTypes);
		var acceptedTier = FirstOrEmpty(line.ActualDataTypes);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result.KeyState = keyState.ToString();
		result.AcceptedState = acceptedState.ToString();

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc) ? null : FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));
		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = acceptedParsed is null ? [] : SingularPhrase(acceptedParsed.HeadTerm);
		var parsedTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		result.KeyHead = string.Join(' ', keyHeadPhrase);

		// 2. pack-unit-state: a can/jar unit in the raw line; the key row is Canned, the accepted row is not.
		if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (acceptedState & FoodState.Canned) == 0)
		{
			return Relation.PackUnitState;
		}

		// 3. compound-head-lost: the key head phrase has two or more words and the parsed name is only its first word.
		if (keyHeadPhrase.Count >= 2 && parsedTokens.Count == 1
			&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return Relation.CompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			return Relation.SiblingFood;
		}

		// 4. state-mismatch: heads agree, state masks differ (both masks recorded on the result).
		if (keyState != acceptedState)
		{
			return Relation.StateMismatch;
		}

		// 5. row-choice-tier: heads and state agree, dataset tier differs. A tier the trace does not
		// carry cannot be compared — §8: classify as other and name the field.
		if (string.IsNullOrEmpty(keyTier) || string.IsNullOrEmpty(acceptedTier))
		{
			result.MissingField = string.IsNullOrEmpty(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
			return Relation.Other;
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return Relation.RowChoiceTier;
		}

		// 6. same-head-other-qualifier: heads and state agree, tiers agree; record the qualifier difference.
		var keyQualifiers = keyParsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToArray();
		var acceptedQualifiers = acceptedParsed is null ? [] : acceptedParsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToArray();
		result.KeyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		result.AcceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		return Relation.SameHeadOtherQualifier;
	}

	private static bool IsKnownPath(string path) =>
		path.Equals(Site.Override, StringComparison.OrdinalIgnoreCase)
		|| path.Equals(Site.Curated, StringComparison.OrdinalIgnoreCase)
		|| path.Equals(Site.Ranker, StringComparison.OrdinalIgnoreCase);

	private static string SiteOf(TraceAtom atom)
	{
		if (atom.Path.Equals(Site.Override, StringComparison.OrdinalIgnoreCase))
		{
			return Site.Override;
		}

		if (atom.Path.Equals(Site.Curated, StringComparison.OrdinalIgnoreCase))
		{
			return Site.Curated;
		}

		return atom.Reused ? Site.Reuse : Site.Ranker;
	}

	private bool IsStateOrModifierWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string FirstOrEmpty(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}
}
