{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines: the
/// <em>relation</em> of the accepted row to the labelled (key) row, and the <em>site</em> that
/// accepted it. Every comparison runs on production helpers — <see cref="FdcNormalizer.NormalizeToTokens(string)"/>,
/// <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/> and
/// <see cref="IngredientLineResolver.SingularizeToken(string)"/> — never a re-implementation (D-014).
/// Not thread-safe: the single-token scratch is shared.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit line accepted on a row without the key's Canned state.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is multi-word and the parsed name kept only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree, state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree, dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads agree, nothing above holds; the qualifier difference is recorded.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: none of the above; a missing trace field, when that is why, is named.</summary>
	public const string Other = "other";

	/// <summary>Site: the ranker accepted a row that was then reused onto an existing master.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker accepted a fresh row.</summary>
	public const string SiteRanker = "ranker";

	private static readonly FdcNormalizer Normalizer = new();

	/// <summary>Shared one-token list for the per-token state probes; the runner is single-threaded.</summary>
	private readonly string?[] _singleToken = new string[1];

	/// <summary>Classifies one auto-wrong trace line.</summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key set for the <c>override</c> site.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(line);
		ArgumentNullException.ThrowIfNull(overrideKeys);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var keyTokens = Normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = Normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var parsedNameTokens = atom is null ? [] : SingularPhrase(atom.ParsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var site = ClassifySite(atom);
		var overrideKey = string.Empty;
		if (site == SiteOverride)
		{
			overrideKey = overrideKeys.IsKey(OverrideLookupKey(line.RawText)) ? "yes" : "no";
		}

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (site.Length == 0)
		{
			return result;
		}

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			result.Relation = PackUnitState;
			return result;
		}

		if (keyPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		if (keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				result.Relation = StateMismatch;
				return result;
			}

			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				result.Relation = Other;
				result.MissingField = string.IsNullOrWhiteSpace(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
				return result;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				result.Relation = RowChoiceTier;
				return result;
			}

			result.Relation = SameHeadOtherQualifier;
			(result.KeyOnlyQualifiers, result.AcceptedOnlyQualifiers) = QualifierDiff(keyDesc, keyTier, acceptedDesc, acceptedTier);
			return result;
		}

		result.Relation = SiblingFood;
		return result;
	}

	/// <summary>
	/// The key head phrase: the key description's normalised tokens up to (excluding) the first token
	/// production state/modifier vocabulary marks as non-head — <see cref="FdcLexicon.ModifierWords"/> or a
	/// non-<see cref="FoodState.None"/> probe through <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/> /
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>. This is what makes
	/// "Bread, crumbs, dry, grated, plain" a two-word head ("bread crumbs") while "Nuts, almonds, blanched"
	/// is not a compound for a line parsed as "almond".
	/// </summary>
	/// <param name="keyTokens">The key description's normalised tokens.</param>
	/// <returns>The head-phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The state ∪ satisfiers mask production computes for a token list.</summary>
	/// <param name="tokens">Normalised tokens.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Folds a raw line text the way the override lookup does: lower-cased, trimmed, content from the first <c>(</c> dropped.</summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string OverrideLookupKey(string rawText)
	{
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

		return text.Trim().ToLowerInvariant();
	}

	private static string ClassifySite(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => string.Empty,
		};
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static IReadOnlyList<string> SingularPhrase(string text) =>
		Normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static (IReadOnlyList<string> KeyOnly, IReadOnlyList<string> AcceptedOnly) QualifierDiff(
		string keyDesc, string keyTier, string acceptedDesc, string acceptedTier)
	{
		var keyQualifiers = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers
			.Select(IngredientLineResolver.SingularizeToken)
			.OrderBy(q => q, StringComparer.OrdinalIgnoreCase)
			.ToHashSet(StringComparer.OrdinalIgnoreCase);
		var acceptedQualifiers = FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers
			.Select(IngredientLineResolver.SingularizeToken)
			.OrderBy(q => q, StringComparer.OrdinalIgnoreCase)
			.ToHashSet(StringComparer.OrdinalIgnoreCase);

		return (keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).ToArray(),
			acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).ToArray());
	}

	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
