/// <summary>Runs the census or pairs subcommand and returns the process exit code.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the invocation; 0 on success, 1 on a missing file, refused set, or unusable arguments.</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>The exit code.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}
","path":"tools/LetUsCook.AutoWrongCensus/Services/IAutoWrongCensusRunner.cs"}

{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>The two console sinks the runner writes to: TSV out, summary/diagnostics err.</summary>
public sealed record OutputWriters(System.IO.TextWriter Output, System.IO.TextWriter Error);

/// <summary>
/// Runs one <c>census</c> or <c>pairs</c> invocation. Refuses any trace whose records carry a
/// <c>set</c> other than <c>debug</c>/<c>batch</c> (D-029) and exits 1 on a missing input.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private const string CensusHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var o = options.Value;
		if (o.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensusAsync(o.TracePath, cancellationToken).ConfigureAwait(false);
		}

		if (o.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairsAsync(o.CensusTsvPath, o.TracePath, cancellationToken).ConfigureAwait(false);
		}

		writers.Error.WriteLine("unusable arguments.");
		AutoWrongCensusUsage.Print();
		return 1;
	}

	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(tracePath))
		{
			writers.Error.WriteLine($"trace not found: {tracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(tracePath, out var readError, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			writers.Error.WriteLine(readError);
			return 1;
		}

		var refused = lines.Select(l => l.Set).Distinct(StringComparer.Ordinal).FirstOrDefault(s => s is not ("debug" or "batch"));
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: trace set '{refused}' — the census reads debug/batch traces only (D-029).");
			return 1;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		writers.Output.WriteLine(CensusHeader);

		var results = new List<ClassificationResult>(autoWrong.Count);
		foreach (var line in autoWrong)
		{
			ClassificationResult result;
			try
			{
				result = classifier.Classify(line);
			}
			catch (InvalidOperationException ex)
			{
				writers.Error.WriteLine(ex.Message);
				return 1;
			}

			if (result.Site.Length == 0)
			{
				writers.Error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault()?.Path}' on {line.HoldoutId}#{line.LineIndex}; refusing to guess a site.");
				return 1;
			}

			results.Add(result);
			writers.Output.WriteLine(ToTsvRow(result));
		}

		WriteSummary(lines.Count, results);
		return 0;
	}

	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath))
		{
			writers.Error.WriteLine($"census tsv not found: {censusTsvPath}");
			return 1;
		}

		if (!File.Exists(tracePath))
		{
			writers.Error.WriteLine($"trace not found: {tracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(tracePath, out var readError, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			writers.Error.WriteLine(readError);
			return 1;
		}

		var refused = lines.Select(l => l.Set).Distinct(StringComparer.Ordinal).FirstOrDefault(s => s is not ("debug" or "batch"));
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: trace set '{refused}' — the census reads debug/batch traces only (D-029).");
			return 1;
		}

		var (windowKeys, censusError) = ReadWindowKeys(censusTsvPath);
		if (windowKeys is null)
		{
			writers.Error.WriteLine(censusError);
			return 1;
		}

		var traceIndex = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex), StringComparer.Ordinal);
		writers.Output.WriteLine(PairsHeader);

		var unmatched = 0;
		foreach (var (holdoutId, lineIndex) in windowKeys)
		{
			if (!traceIndex.TryGetValue((holdoutId, lineIndex), out var line) || line.Atoms.Count == 0)
			{
				unmatched++;
				continue;
			}

			var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms[0];
			writers.Output.WriteLine(string.Join('\t',
				holdoutId,
				lineIndex.ToString(),
				Sanitize(classifier.FoldedName(atom.ParsedName)),
				Sanitize(classifier.KeyHeadPhraseOf(First(line.ExpectedDescriptions))),
				Sanitize(line.RawText)));
		}

		writers.Error.WriteLine($"pairs emitted={windowKeys.Count - unmatched} unmatched={unmatched}");
		return 0;
	}

	/// <summary>The stderr summary: relation × site matrix plus the per-class detail rows.</summary>
	private void WriteSummary(int traced, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		writers.Error.WriteLine($"autoWrongCensus set={set} traced={traced} autoWrong={results.Count}");

		foreach (var (relation, site, count) in results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.Relation, StringComparer.Ordinal)
			.ThenBy(t => t.Site, StringComparer.Ordinal))
		{
			writers.Error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0):0.0}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField!)
			.Select(g => $"{g.Key}={g.Count()}")
			.OrderBy(s => s, StringComparer.Ordinal);
		writers.Error.WriteLine($"missingFields: {(missing.Any() ? string.Join(' ', missing) : "none")}");

		var overrideResults = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideResults.Count > 0)
		{
			writers.Error.WriteLine($"overrideKey yes={overrideResults.Count(r => r.OverrideKey == "yes")} no={overrideResults.Count(r => r.OverrideKey == "no")}");
		}

		var reuseResults = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseResults.Count > 0)
		{
			var linked = reuseResults.Where(r => !string.IsNullOrEmpty(r.LinkedIngredientId)).ToList();
			var shouldReuseFalse = linked.Count(r => !IngredientLineResolver.ShouldReuse(
				IngredientLineParser.ComputeSlug(r.ParsedName),
				r.LinkedIngredientId!));
			writers.Error.WriteLine($"reuse-site ShouldReuse(parsedName, linkedIngredientId) false: {shouldReuseFalse} of {linked.Count}");
		}

		var tierResults = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierResults.Count > 0)
		{
			writers.Error.WriteLine($"row-choice-tier key higher={tierResults.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tierResults.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers!)}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers!)}]");
		}
	}

	// Foundation > SrLegacy > Survey > Branded (brief §4).
	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private static string ToTsvRow(ClassificationResult r) => string.Join('\t',
		Sanitize(r.HoldoutId),
		r.LineIndex.ToString(),
		Sanitize(r.Set),
		r.Relation,
		r.Site,
		r.OverrideKey,
		Sanitize(r.AcceptedTier),
		Sanitize(r.KeyTier),
		r.AcceptedState,
		r.KeyState,
		Sanitize(r.ParsedName),
		Sanitize(r.KeyHead),
		Sanitize(r.AcceptedDesc),
		Sanitize(r.KeyDesc),
		Sanitize(r.RawText));

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static async Task<List<TraceLine>?> ReadTraceAsync(string tracePath, out string error, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		try
		{
			var lineNumber = 0;
			await foreach (var line in File.ReadLinesAsync(tracePath).WithCancellation(cancellationToken).ConfigureAwait(false))
			{
				lineNumber++;
				if (string.IsNullOrWhiteSpace(line))
				{
					continue;
				}

				lines.Add(JsonSerializer.Deserialize<TraceLine>(line, JsonOptions)
					?? throw new JsonException($"line {lineNumber} deserialized to null"));
			}
		}
		catch (JsonException ex)
		{
			error = $"trace parse failed: {tracePath}: {ex.Message}";
			return null;
		}

		error = string.Empty;
		return lines;
	}

	/// <summary>The P12.7 census rows with <c>blocker=window</c> and <c>route</c> in {compound, other}, in file order.</summary>
	private static (IReadOnlyList<(string HoldoutId, int LineIndex)>? Keys, string Error) ReadWindowKeys(string censusTsvPath)
	{
		var header = File.ReadLines(censusTsvPath).FirstOrDefault() ?? string.Empty;
		var columns = header.Split('\t');
		if (columns.Length < 4
			|| !columns.Contains("holdoutId")
			|| !columns.Contains("lineIndex")
			|| !columns.Contains("blocker")
			|| !columns.Contains("route"))
		{
			return (null, $"census tsv header missing holdoutId/lineIndex/blocker/route columns: {censusTsvPath}");
		}

		var idIdx = Array.IndexOf(columns, "holdoutId");
		var lineIdx = Array.IndexOf(columns, "lineIndex");
		var blockerIdx = Array.IndexOf(columns, "blocker");
		var routeIdx = Array.IndexOf(columns, "route");

		var keys = new List<(string, int)>();
		foreach (var line in File.ReadLines(censusTsvPath).Skip(1))
		{
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			var cells = line.Split('\t');
			if (cells.Length <= Math.Max(lineIdx, Math.Max(blockerIdx, routeIdx)))
			{
				continue;
			}

			if (!cells[blockerIdx].Equals("window", StringComparison.Ordinal)
				|| (cells[routeIdx] != "compound" && cells[routeIdx] != "other"))
			{
				continue;
			}

			if (!int.TryParse(cells[lineIdx], out var lineIndex))
			{
				return (null, $"census tsv lineIndex not an int: '{cells[lineIdx]}'");
			}

			keys.Add((cells[idIdx], lineIndex));
		}

		return (keys, string.Empty);
	}
}
