/// <summary>
/// The raw-key set of <c>Lexicon/Resources/exact-overrides.json</c>, read from the LetUsCook.Fdc
/// assembly's embedded resource — the same bytes production ships, not a copy of its contents.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly HashSet<string> _keys;

	/// <summary>Loads the key set from the embedded <c>exact-overrides.json</c>.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(LetUsCook.Fdc.Lexicon.FdcNormalizer).Assembly;
		var resourceName = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(resourceName)
			?? throw new InvalidOperationException($"Embedded resource '{resourceName}' not found.");

		using var reader = new StreamReader(stream);
		using var document = JsonDocument.Parse(reader.ReadToEnd());

		_keys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var property in document.RootElement.EnumerateObject())
		{
			_keys.Add(property.Name);
		}
	}

	/// <summary>Returns <see langword="true"/> when <paramref name="normalizedRawText"/> is a key in <c>exact-overrides.json</c>.</summary>
	/// <param name="normalizedRawText">The raw line text folded for lookup (lower-cased, trimmed, content from the first <c>(</c> dropped).</param>
	/// <returns>Whether the folded text is a key.</returns>
	public bool IsKey(string normalizedRawText) => _keys.Contains(normalizedRawText);
}
